/* SNN aile değişkenleri (token). Arc foundation.css'ten uyarlanmıştır (kuratlielia/arc-library, commit bfdf7e8, MIT).
   Arc'tan farkları (ayrıntı: KAYNAK.md):
     - --warning amber değil, mavi-gridir. Aile kuralı amber/turuncuyu yasaklar (SNN-Standartlar/standartlar/arayuz-standardi.md §1).
     - data-accent="amber" ve data-accent="orange" seçenekleri yok.
     - Arc marka geçişi (--arc-gradient*) yok: tonu şeftaliydi (amber aralığı) ve ilk raftaki hiçbir bileşen kullanmıyor.
     - Grafik serisi paleti (--series-*) yok: yedek renklerden biri amberdi, göreli renk formülü de vurguya göre amber üretebiliyordu.
       Grafikler 2. rafta (aşama 3) amber olmadan yeniden kurulur.
   Bu dosyada amber tonu kalırsa test/amber.test.mjs kırmızı olur. Vurgu rengi proje başına seçilir: <html data-accent="blue">. */
/* Yazı tipleri: Inter (gövde) ve Geist (başlık), ikisi de OFL lisanslı, npm paketinden gelir (snn-foundation kurulumu paketleri ekler).
   Türkçe harfler (ğ ş ı İ) latin-ext alt kümesindedir; paketin varsayılan girişi onu da içerir. @import dosyanın en başında kalmalıdır. */
@import "@fontsource-variable/inter";
@import "@fontsource-variable/geist";

:root {
  color-scheme: light;
  --neutral-0: oklch(100% 0 0);
  --neutral-1: oklch(99% 0 0);
  --neutral-2: oklch(97.8% 0 0);
  --neutral-3: oklch(95.8% 0 0);
  --neutral-4: oklch(91.5% 0 0);
  --neutral-5: oklch(84% 0 0);
  --neutral-6: oklch(72% 0 0);
  --neutral-7: oklch(59% 0 0);
  --neutral-8: oklch(46% 0 0);
  --neutral-9: oklch(34% 0 0);
  --neutral-10: oklch(23% 0 0);
  --neutral-11: oklch(15% 0 0);
  --background: var(--neutral-0);
  --surface: var(--neutral-0);
  --surface-raised: var(--neutral-0);
  --surface-muted: var(--neutral-2);
  --foreground: var(--neutral-11);
  --text-secondary: var(--neutral-8);
  --text-muted: var(--neutral-7);
  --border: oklch(93.5% 0 0);
  --border-subtle: oklch(96.5% 0 0);
  --border-strong: oklch(82% 0 0);
  --accent: oklch(33% 0 0);
  --accent-strong: oklch(24% 0 0);
  --accent-subtle: oklch(33% 0 0 / .1);
  --accent-foreground: var(--background);
  /* Seçim denetimleri (anahtar, onay kutusu, radyo, kaydırıcı). --control-on seçili denetimin dolgusu, --control-glyph üstündeki işaret ya da nokta.
     Topuzlar iki durumda da beyaz kalır; her vurguda okunsun diye aşağıda vurgu başına ayarlanır. */
  --control-on: oklch(23% 0 0);
  --control-glyph: oklch(100% 0 0);
  --control-track: oklch(89.5% 0 0);
  --control-track-hover: oklch(86% 0 0);
  --control-thumb: oklch(100% 0 0);
  --control-thumb-on: oklch(100% 0 0);
  --control-thumb-shadow: 0 0 0 .5px oklch(0% 0 0 / .07), 0 1px 2px oklch(0% 0 0 / .14), 0 2px 6px oklch(0% 0 0 / .06);
  --control-on-subtle: color-mix(in oklab, var(--control-on) 10%, transparent);
  /* Kaydırıcı dolgusu. --control-on ile aynıdır; yalnız koyu nötr temada beyaz topuz ayrışsın diye orta gri olur. */
  --control-fill: var(--control-on);
  /* Fareyle odaklanınca halka çizilmez (Arc ürün kararı). Klavye odağı dosyanın sonundaki çerçeveyle gösterilir;
     --focus-outline, --focus-outline-width ve --focus-outline-offset ile ayarlanır. */
  --focus-ring: transparent;
  /* Durum renkleri. Uyarı amber değildir: mavi-gri (aile kuralı). Kırmızı yalnız gerçek hata içindir. */
  --success: oklch(49% .19 150);
  --warning: oklch(50% .09 255);
  --danger: oklch(54% .21 25);
  --shadow-resting: 0 1px 2px oklch(0% 0 0 / .035);
  --shadow-raised: 0 6px 18px oklch(0% 0 0 / .065), 0 1px 3px oklch(0% 0 0 / .035);
  --shadow-floating: 0 20px 48px oklch(0% 0 0 / .105), 0 3px 10px oklch(0% 0 0 / .045);
  --space-1: .25rem; --space-2: .5rem; --space-3: .75rem; --space-4: 1rem;
  --space-5: 1.25rem; --space-6: 1.5rem; --space-8: 2rem; --space-10: 2.5rem;
  --space-12: 3rem; --space-16: 4rem; --space-20: 5rem; --space-24: 6rem;
  --radius-control: 1.125rem; --radius-panel: 1.625rem; --radius-surface: 2.125rem; --radius-pill: 9999px;
  --control-height-sm: 2.25rem; --control-height-md: 2.75rem; --control-height-lg: 3.125rem;
  --font-display: var(--font-geist, "Geist Variable"), sans-serif;
  --font-body: var(--font-inter, "Inter Variable"), sans-serif;
  --text-xs: .75rem; --text-sm: .875rem; --text-base: 1rem; --text-lg: 1.125rem;
  --text-xl: 1.375rem; --text-2xl: 1.75rem; --text-3xl: 2.25rem;
  --text-4xl: 3.25rem; --text-5xl: 4.5rem;
  --tracking-display: -.03em; --tracking-body: -.01em;
  --leading-display: 1.1; --leading-body: 1.4;
  --ease-enter: cubic-bezier(.16,1,.3,1);
  --ease-standard: cubic-bezier(.22,1,.36,1);
  --ease-exit: cubic-bezier(.7,0,.84,0);
  --ease-in-out: cubic-bezier(.65,0,.35,1);
  /* Hafif oturan yay (sekme .15). Dönüşüm geçişlerinde --duration-spring ile birlikte kullanılır. */
  --ease-spring: linear(0, 0.0258, 0.09, 0.1763, 0.2732, 0.3724, 0.4683, 0.5573, 0.6376, 0.7082, 0.7689, 0.8202, 0.8628, 0.8976, 0.9256, 0.9476, 0.9648, 0.9778, 0.9875, 0.9945, 0.9994, 1.0026, 1.0047, 1.0058, 1.0062, 1.0062, 1.0059, 1.0055, 1.0049, 1.0043, 1.0036, 1.0031, 1.0025, 1.002, 1.0016, 1.0013, 1);
  --duration-instant: 120ms; --duration-fast: 160ms; --duration-standard: 240ms; --duration-considered: 480ms; --duration-spring: 580ms;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --background: oklch(19% 0 0);
  --surface: oklch(21.5% 0 0);
  --surface-raised: oklch(24% 0 0);
  /* Koyu temada soluk yüzey ve üzerine gelme durumu temel yüzeyden ayrışsın. */
  --surface-muted: oklch(26% 0 0);
  --foreground: oklch(96% 0 0);
  --text-secondary: oklch(77% 0 0);
  --text-muted: oklch(64% 0 0);
  --border: oklch(29% 0 0);
  --border-subtle: oklch(25% 0 0);
  --border-strong: oklch(40% 0 0);
  --focus-ring: transparent;
  --accent: oklch(80% 0 0);
  --accent-strong: oklch(91% 0 0);
  --accent-subtle: oklch(80% 0 0 / .13);
  /* Koyu nötrde ters çevrilir: beyaza yakın iz koyu topuz taşır, açık ve kapalı birbirine benzemez. */
  --control-on: oklch(93% 0 0);
  --control-glyph: oklch(19% 0 0);
  --control-track: oklch(33% 0 0);
  --control-track-hover: oklch(37% 0 0);
  --control-thumb: oklch(97% 0 0);
  --control-thumb-on: oklch(19% 0 0);
  --control-fill: oklch(62% 0 0);
  --control-thumb-shadow: 0 0 0 .5px oklch(0% 0 0 / .3), 0 1px 2px oklch(0% 0 0 / .35), 0 2px 6px oklch(0% 0 0 / .2);
  --success: oklch(78% .18 150);
  --warning: oklch(78% .08 255);
  --danger: oklch(76% .2 25);
  --shadow-resting: 0 1px 2px oklch(0% 0 0 / .18);
  --shadow-raised: 0 8px 22px oklch(0% 0 0 / .22);
  --shadow-floating: 0 22px 55px oklch(0% 0 0 / .34);
}

/* Vurgu seçenekleri. Proje kendi vurgusunu <html data-accent="..."> ile seçer. Amber ve turuncu bilerek yoktur. */
:root[data-accent="neutral"] { --accent: oklch(33% 0 0); --accent-strong: oklch(24% 0 0); --accent-subtle: oklch(33% 0 0 / .1); }
:root[data-accent="violet"] { --accent: #7747ff; --accent-strong: #5528ce; --accent-subtle: rgb(119 71 255 / .13); }
:root[data-accent="blue"] { --accent: #0562ef; --accent-strong: #074db7; --accent-subtle: rgb(5 98 239 / .12); }
:root[data-accent="green"] { --accent: #0db879; --accent-strong: #087c54; --accent-subtle: rgb(13 184 121 / .13); --accent-foreground: #102016; }
:root[data-accent="coral"] { --accent: #f15f55; --accent-strong: #b92c27; --accent-subtle: rgb(241 95 85 / .14); --accent-foreground: #21110f; }
:root[data-accent="rose"] { --accent: #ed4e9d; --accent-strong: #ae2570; --accent-subtle: rgb(237 78 157 / .14); --accent-foreground: #250f1b; }
:root[data-theme="dark"][data-accent="neutral"] { --accent: oklch(80% 0 0); --accent-strong: oklch(91% 0 0); --accent-subtle: oklch(80% 0 0 / .13); }
:root[data-theme="dark"][data-accent="violet"] { --accent: #a78bff; --accent-strong: #c7b7ff; --accent-subtle: rgb(119 71 255 / .22); }
:root[data-theme="dark"][data-accent="blue"] { --accent: #6ba3ff; --accent-strong: #a4c7ff; --accent-subtle: rgb(5 98 239 / .22); }
:root[data-theme="dark"][data-accent="green"] { --accent: #53dca6; --accent-strong: #93efd0; --accent-subtle: rgb(13 184 121 / .2); }
:root[data-theme="dark"][data-accent="coral"] { --accent: #ff9386; --accent-strong: #ffc1ba; --accent-subtle: rgb(241 95 85 / .2); }
:root[data-theme="dark"][data-accent="rose"] { --accent: #ff8bc5; --accent-strong: #ffc0df; --accent-subtle: rgb(237 78 157 / .2); }

/* Seçim denetimlerinin vurguya göre dolgusu. Açık temada vurgunun kendisi (beyaz topuz için gerekirse biraz koyulaştırılmış).
   Koyu temada pastel metin vurgusu yerine orta ton: beyaz topuz ve işaret okunur kalır, iz parlamaz. */
:root[data-accent="neutral"] { --control-on: oklch(23% 0 0); --control-thumb-on: oklch(100% 0 0); --control-glyph: oklch(100% 0 0); }
:root[data-accent="violet"] { --control-on: #7747ff; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="blue"] { --control-on: #0562ef; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="green"] { --control-on: #10a870; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="coral"] { --control-on: #ec564b; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-accent="rose"] { --control-on: #e64494; --control-thumb-on: #fff; --control-glyph: #fff; }
:root[data-theme="dark"][data-accent="neutral"] { --control-on: oklch(93% 0 0); --control-thumb-on: oklch(19% 0 0); --control-glyph: oklch(19% 0 0); }
:root[data-theme="dark"][data-accent="violet"] { --control-on: #8a66ff; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #8a66ff; }
:root[data-theme="dark"][data-accent="blue"] { --control-on: #3b82f6; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #3b82f6; }
:root[data-theme="dark"][data-accent="green"] { --control-on: #1fae78; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #1fae78; }
:root[data-theme="dark"][data-accent="coral"] { --control-on: #ec6a60; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #ec6a60; }
:root[data-theme="dark"][data-accent="rose"] { --control-on: #e457a0; --control-thumb-on: #fff; --control-glyph: #fff; --control-fill: #e457a0; }

/* Odak. Fareyle odakta halka çizilmez (Arc ürün kararı). Klavye odağı (:focus-visible) ince bir vurgu çerçevesi çizer; klavye kullanan
   nerede olduğunu hep görür (WCAG 2.4.7). Çerçeve dışında kalanlar: metin alanları (fare tıklamasında da :focus-visible olurlar, odağı
   kenarlık ve imleç gösterir), menü öğeleri ve liste seçenekleri (vurgu dolgusu klavye konumunu gösterir) ve yalnız betikle odak alan
   tabindex="-1" hedefleri (pencere panelleri, bölgeler).
   :root ya da herhangi bir öğede ayarlanır, !important gerekmez:
     --focus-outline           renk (varsayılan: yumuşatılmış vurgu); gizlemek için transparent
     --focus-outline-width     varsayılan 2px
     --focus-outline-offset    varsayılan 2px; kırpılmış kap içindeki bileşenler eksi değer verir */
:focus:not(:focus-visible),
:is(input:not([type="button"], [type="checkbox"], [type="color"], [type="file"], [type="image"], [type="radio"], [type="range"], [type="reset"], [type="submit"]), textarea, [contenteditable]:not([contenteditable="false"]), [role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"], [tabindex="-1"]):focus { outline: none !important; }
:focus-visible:not(input:not([type="button"], [type="checkbox"], [type="color"], [type="file"], [type="image"], [type="radio"], [type="range"], [type="reset"], [type="submit"]), textarea, [contenteditable]:not([contenteditable="false"]), [role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"], [tabindex="-1"]) {
  outline: var(--focus-outline-width, 2px) solid var(--focus-outline, color-mix(in oklab, var(--accent-strong) 72%, transparent)) !important;
  outline-offset: var(--focus-outline-offset, 2px) !important;
}

/* Gövde yazı tipi ve form öğeleri. Tarayıcı düğme ve alanları kendi yazı tipiyle (Arial 13,33 px) çizer; miras aldırılır.
   :where ile özgüllük sıfırdır: projenin ya da bileşenin kendi kuralı her zaman önce gelir. */
:where(body) { font-family: var(--font-body); }
:where(button, input, select, textarea) { font: inherit; }
